-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "deDE" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.rogue.dps.Name"] = "Nahkampf-DPS"
L["rm.era.rogue.dps.Description"] = "Stufen 1–60, jede Spezialisierung, auch auf Hardcore- und Self-Found-Realms; zusammengestellt aus Simulation, Icy Veins und Wowhead. Aus der Verstohlenheit: Konzentration, Hinterhalt mit einem Dolch, wenn das Ziel Ihnen nicht zugewandt ist, Fieser Trick solo, Erdrosseln außerhalb von Schlachtzügen. Im Kampf: Riposte, Zerhäckseln ab einem Combopunkt, wenn es auf einem Elitegegner oder einem Ziel mit viel Gesundheit fehlt (bei fünf Punkten in seinen letzten drei Sekunden erneuert), Rüstung schwächen bei fünf Punkten in einer Gruppe, wenn Sie Verbessertes Rüstung schwächen 2/2 haben und niemand Rüstung zerreißen nutzt, Ausweiden mit zwei Punkten auf ein Ziel kurz vor dem Tod, sonst Ausweiden bei fünf und kein Aufbauangriff über fünf hinaus. Der Aufbauangriff richtet sich danach, was Sie beherrschen: Geisterhafter Stoß und Blutsturz außerhalb von Schlachtzügen, Meucheln mit einem Dolch, wenn das Ziel Ihnen nicht zugewandt ist, sonst Finsterer Stoß. Erinnerungen: Gifte auf jeder Waffe (Tödliches Gift auf einer Schildhandwaffe, wenn vorhanden), Tritt, Disteltee, Klingenwirbel und Adrenalinrausch gegen Elitegegner oder zwei Gegner bei aktivem Zerhäckseln, Kaltblütigkeit bei fünf Punkten, Entrinnen solo bei Verletzung. Verschwinden, Solarplexus, Vorbereitung, Nierenhieb und Volksfähigkeiten sind als deaktivierte Schritte aufgeführt; Finte, Sprinten, Blenden, Kopfnuss und Positionierung bleiben Ihnen überlassen."
L["rm.era.rogue.dps.simulator.Name"] = "Schwerter, Finsterer Stoß im Schlagtakt (Simulation)"
L["rm.era.rogue.dps.simulator.Description"] = "Die „schweißtreibende“ Kampf-Reihenfolge von Simulation für Schwert-Spezialisierung, eine Alternative zur empfohlenen integrierten Nahkampf-DPS-Rotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Finsterer Stoß nur direkt nach einem Schlag der Waffenhand (2,0 Sekunden oder mehr bis zum nächsten, eingestellt für ein Schwert mit Geschwindigkeit 2,6–2,8; ändern Sie es in einer Kopie), außer die Energie ist fast voll oder das Ziel stirbt gleich, damit der zusätzliche Schwertangriff Ihren Schlag nicht verzögert. Ausweiden bei fünf Punkten wartet außerdem auf Zerhäckseln, volle Energie oder ein sterbendes Ziel. Ansonsten wie die empfohlene integrierte Rotation."
L["rm.era.rogue.dps.warcrafttavern.Name"] = "Nahkampf-DPS, Finisher mit fünf Punkten (Warcraft Tavern)"
L["rm.era.rogue.dps.warcrafttavern.Description"] = "Die Spielweise von Warcraft Tavern, eine Alternative zur empfohlenen integrierten Nahkampf-DPS-Rotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Jeder Finisher wartet auf fünf Combopunkte, damit Unerbittliche Stöße ihn zurückerstattet. Zerhäckseln wird ab seinem zweiten Rang (Stufe 42) genutzt, wenn es fehlt oder ausläuft, sonst Ausweiden; kein Zerhäckseln mit wenigen Punkten, kein Ausweiden kurz vor dem Tod des Ziels und kein Rüstung schwächen (Rüstung zerreißen eines Kriegers deckt das ab). Dieselben Eröffner, Aufbauangriffe und Erinnerungen wie die empfohlene integrierte Rotation."
L["rm.forever.rogue.dps.Name"] = "Nahkampf-DPS"
L["rm.forever.rogue.dps.Description"] = "Nahkampfschaden für jede Schurken-Spezialisierung von Stufe 1 bis 60, zusammengestellt aus Icy Veins, Wowhead und Warcraft Tavern. Der Aufbauangriff richtet sich danach, was Sie beherrschen: Verstümmeln (Finsterer Stoß für den fünften Punkt), Blutsturz, Meucheln, wenn das Ziel Ihnen nicht zugewandt ist, sonst Finsterer Stoß. Aus der Verstohlenheit eröffnet sie mit Konzentration, Fieser Trick beim Solospiel, Erdrosseln für Täuschung gegen Elitegegner in der Gruppe, sonst Hinterhalt oder Erdrosseln. Sie hält Zerhäckseln und Toxin aufrecht, nutzt Rüstung schwächen in Gruppen gegen Elitegegner, wenn kein Krieger fünfmal Rüstung zerreißen aufgebracht hat, gibt dann fünf Punkte für Blutung (Täuschung, lange Kämpfe) oder Ausweiden aus und baut nie über fünf Punkte hinaus auf. Erinnerungen: Gifte auf jeder Waffe, Tritt, Klingenwirbel und Adrenalinrausch gegen Gruppen und Elitegegner, Kaltblütigkeit, Entrinnen, Finte, Distelteetee und Vorbereitung. Ihnen überlassen: Verschwinden, Sprinten, Nierenhieb, Blenden, Kopfnuss und Positionierung. Forever schränkt Kampfdaten ein, daher führt Rotation Master diese integrierte Rotation nur zur Referenz auf und wählt sie noch nicht automatisch aus."
L["rm.forever.rogue.subtlety.warcrafttavern.Name"] = "Täuschung, Hinterhalt-Build (Warcraft Tavern)"
L["rm.forever.rogue.subtlety.warcrafttavern.Description"] = "Täuschungs-Build mit Hinterhalt/Halsabschneider nach Warcraft Tavern: Konzentration und Hinterhalt bei jeder Eröffnung, erneut Hinterhalt, wann immer Halsabschneider es erlaubt, Meucheln von hinten als Aufbauangriff (Blutsturz, wenn das Ziel Ihnen zugewandt ist), Geisterhafter Stoß bei Abklingzeit-Ende sowie Zerhäckseln und dann Ausweiden bei fünf Punkten, ohne Blutung. Erinnert Sie daran, gegen einen getankten Boss für einen weiteren Hinterhalt Verschwinden zu nutzen. Wählen Sie diese statt der empfohlenen integrierten Schurkenrotation, wenn Sie die Halsabschneider-Talente gewählt haben; sie gilt, wenn Täuschung Ihr Haupttalentbaum ist und Halsabschneider als Talent gewählt ist. Dieselben Erinnerungen an Gifte und Abklingzeiten wie die empfohlene integrierte Rotation. Eine Alternative zur empfohlenen integrierten Schurken-DPS-Rotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität."
L["rm.forever.rogue.subtlety.wowhead.Name"] = "Täuschung, Erdrosseln-Build (Wowhead)"
L["rm.forever.rogue.subtlety.wowhead.Description"] = "Täuschung nach Wowhead: Konzentration und Erdrosseln bei jeder Eröffnung, und Verschwinden (danach Vorbereitung) wird in der Rotation genutzt, um erneut mit Erdrosseln zu eröffnen, sobald das letzte ausgelaufen ist. Zerhäckseln wird aufrechterhalten, Rüstung schwächen in Gruppen, Blutung als Finisher mit fünf Punkten, Blutsturz als einziger Aufbauangriff. Dies verbraucht Verschwinden, Ihre Fluchtmöglichkeit, für Schaden: Wählen Sie es bewusst. Es gilt, wenn Täuschung Ihr Haupttalentbaum ist, Schmutzige Tricks als Talent gewählt ist und Konzentration bekannt ist. Dieselben Erinnerungen an Gifte und Abklingzeiten wie die empfohlene integrierte Rotation. Eine Alternative zur empfohlenen integrierten Schurken-DPS-Rotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität."
L["rm.mop.rogue.assassination.Name"] = "Empfohlen"
L["rm.mop.rogue.assassination.Description"] = "Empfohlen für Meucheln von Stufe 10 bis 90 (Simulation und Wowhead für Phase 5, mit den Leveling-Schritten von Icy Veins). Eröffnet aus der Verstohlenheit solo mit Fieser Trick, sonst mit Verstümmeln (Tötung bei Überrumpeln, mit einem Dolch). Hält Zerhäckseln aufrecht (ab Stufe 60 erneuert Vergiften es) und Blutung auf dem Ziel, gibt fünf Punkte für Vergiften aus, solange Blutung anhält, und vier Punkte, um den Stärkungszauber von Vergiften am Laufen zu halten, wenn Sie Erwartung nicht haben, dann Todesurteil, Tötung unter 35 % oder bei Überrumpeln (dafür ist ein Dolch in der Waffenhand nötig) und Verstümmeln. Wenn vier oder mehr Gegner gegen Sie kämpfen: Zerhäckseln, Blutroter Sturm bei sieben, Blutung, Vergiften und Dolchfächer; Blutung per Tab-Wechsel auf andere Ziele zu verteilen bleibt Ihnen überlassen. Solo kommen Gesundung und ein Nierenhieb bei niedriger Gesundheit hinzu. Erinnerungen: Gifte, Tritt, Vendetta bei langen Kämpfen, Schattenklingen mit Vendetta, Verschwinden und Vorbereitung während Vendetta, Schattenschritt aus der Distanz, Entrinnen solo. Ihnen überlassen: Schurkenhandel und Rüstung schwächen (aufgeführt, aber deaktiviert), Finte, Sprinten und Positionierung."
L["rm.mop.rogue.assassination.icyveins.Name"] = "Vergiften bei fünf Punkten (Icy Veins)"
L["rm.mop.rogue.assassination.icyveins.Description"] = "Standardmäßig deaktiviert. Die Reihenfolge von Icy Veins und Method: Verschwinden bei Abklingzeit-Ende für ein Verstümmeln aus der Verstohlenheit, Vendetta bei Abklingzeit-Ende, wenn der Kampf lang genug ist, Vergiften nur bei fünf Punkten, Blutung aufrechterhalten, Tötung unter 35 % oder bei Überrumpeln, Verstümmeln. Vier bis acht Gegner: Dolchfächer mit Blutung ab drei Punkten; neun oder mehr: nur Dolchfächer und Vergiften. Die empfohlene integrierte Meucheln-Rotation folgt stattdessen den neueren Empfehlungen für Phase 5; um diese zu verwenden, aktivieren Sie sie und deaktivieren Sie die empfohlene."
L["rm.mop.rogue.combat.Name"] = "Empfohlen"
L["rm.mop.rogue.combat.Description"] = "Empfohlen für Kampf von Stufe 10 bis 90 (Wowhead und Simulation für Phase 5). Seit dem Patch zur Schlacht um Orgrimmar kostet Finsterer Stoß 50 Energie, daher ist Enthüllender Stoß der Aufbauangriff, und Finsterer Stoß wird nur während Kampfrausch oder Heldentum mit Adrenalinrausch (und vor Stufe 20) genutzt. Eröffnet solo mit Fieser Trick, sonst mit Hinterhalt. Hält Zerhäckseln ab zwei Punkten aufrecht und Enthüllender Stoß auf dem Ziel, gibt fünf Punkte nur aus, solange Enthüllender Stoß aktiv ist (Zerhäckseln, Blutung bei einem langen Einzelzielkampf ohne Klingenwirbel, Ausweiden), und wartet bei fünf Punkten auf Energie. Gegen acht oder mehr Gegner: Zerhäckseln, Blutroter Sturm und Dolchfächer. Solo kommen Gesundung und Nierenhieb hinzu. Erinnerungen: Gifte, Tritt, Klingenwirbel gegen zwei oder mehr Gegner an und wieder aus, Adrenalinrausch bei wenig Energie mit Schattenklingen, Mordlust, Verschwinden und Vorbereitung für Hinterhalt während Tiefe Einsicht, Schattenschritt, Entrinnen solo. Ihnen überlassen: Schurkenhandel und Rüstung schwächen (aufgeführt, aber deaktiviert), Finte und die Positionierung hinter dem Ziel für Hinterhalt."
L["rm.mop.rogue.combat.hekili.Name"] = "Erwartung (Hekili)"
L["rm.mop.rogue.combat.hekili.Description"] = "Standardmäßig deaktiviert. Die MoP-Reihenfolge von Hekili für Kampf mit Erwartung: Enthüllender Stoß ist der einzige Aufbauangriff, selbst während Kampfrausch; Finisher warten auf Tiefe Einsicht, vier Aufladungen von Erwartung oder die Rückkehr von Schattenklingen, dann Zerhäckseln, Blutung auf einem oder zwei langlebigen Zielen, Blutroter Sturm bei sieben Gegnern und Ausweiden; Zerhäckseln wird bei 11 Stapeln Arglist des Banditen vorzeitig erneuert; Dolchfächer ab vier Gegnern. Sie gilt nur mit dem Talent Erwartung. Aktivieren Sie sie und deaktivieren Sie die empfohlene integrierte Kampf-Rotation, um sie zu verwenden."
L["rm.mop.rogue.combat.icyveins.Name"] = "Finsterer Stoß als Aufbauangriff (Icy Veins)"
L["rm.mop.rogue.combat.icyveins.Description"] = "Standardmäßig deaktiviert und für Phase 5 überholt. Die Reihenfolge von Icy Veins, Warcraft Tavern, Method und wowtbc.gg aus der Zeit vor dem Patch zur Schlacht um Orgrimmar: Zerhäckseln, Enthüllender Stoß aufrechterhalten, Blutung mit fünf Punkten bei einem langen Einzelzielkampf und Ausweiden, mit Finsterer Stoß als Aufbauangriff. Dieselben Erinnerungen und dasselbe Spiel gegen Gruppen wie die empfohlene integrierte Kampf-Rotation. Wählen Sie sie nur, wenn Sie diesen Leitfäden folgen; aktivieren Sie sie und deaktivieren Sie die empfohlene."
L["rm.mop.rogue.subtlety.Name"] = "Empfohlen"
L["rm.mop.rogue.subtlety.Description"] = "Empfohlen für Täuschung mit Schattenfokus von Stufe 10 bis 90 (Simulation und Wowhead für Phase 5). In Verstohlenheit oder Schattentanz: Konzentration, Zerhäckseln vor dem Pull, Finisher bei fünf Punkten, Hinterhalt, Erdrosseln. Außerhalb: Zerhäckseln; bei fünf Punkten Zerhäckseln und Blutung, wenn sie bald auslaufen, Ausweiden, solange beide anhalten; Todesurteil; Blutsturz, um seine Blutung zu halten; Meucheln (mit einem Dolch), wenn das Ziel Sie nicht angreift, sonst Blutsturz. Gegen drei oder mehr Gegner: Zerhäckseln, Blutroter Sturm, Ausweiden und Dolchfächer. Solo kommen Gesundung und Nierenhieb hinzu. Erinnerungen: Gifte, Tritt, Schattentanz bei 75 Energie mit aktivem Zerhäckseln und aktiver Blutung, Verschwinden, wenn Schwächen aufspüren ausläuft, Vorbereitung, Schattenklingen außerhalb von Schattentanz und Verstohlenheit, Schattenschritt, Entrinnen solo. Ihnen überlassen: hinter dem Ziel zu stehen (RM kann die Blickrichtung nicht sehen), Schurkenhandel und Rüstung schwächen (aufgeführt, aber deaktiviert)."
L["rm.mop.rogue.subtlety.warcrafttavern.Name"] = "Trickbetrug (Warcraft Tavern)"
L["rm.mop.rogue.subtlety.warcrafttavern.Description"] = "Automatisch statt der integrierten Rotation mit Schattenfokus gewählt, wenn Ihr Talent der Stufe 1 Trickbetrug ist (der Build von Warcraft Tavern). Konzentration und Zerhäckseln vor dem Pull; in Verstohlenheit, Schattentanz oder der Nachwirkung von Trickbetrug Finisher bei fünf Punkten und dann Hinterhalt, so oft er trifft. Zwei oder drei Gegner: Blutung aufrechterhalten und fünf Punkte für Blutroter Sturm statt Ausweiden ausgeben; ab vier kommt Dolchfächer hinzu. Ein Ziel: Zerhäckseln, Blutung, Ausweiden, Blutsturz für seine Blutung, Meucheln von hinten mit einem Dolch, sonst Blutsturz. Schattentanz und Verschwinden sind Erinnerungen bei 60 Energie mit aktivem Zerhäckseln; sie auf Schmuck-Procs abzustimmen, wie Tavern empfiehlt, bleibt Ihnen überlassen."
L["rm.mop.rogue.unspecialized.Name"] = "Ohne Spezialisierung"
L["rm.mop.rogue.unspecialized.Description"] = "Für Stufe 1 bis 9 oder einen Schurken, der noch keine Spezialisierung gewählt hat; die integrierte Rotation jeder Spezialisierung übernimmt, sobald Sie eine wählen. Eröffnet aus der Verstohlenheit solo mit Fieser Trick, mit Hinterhalt oder Finsterer Stoß; schlägt außerhalb des Kampfes Verstohlenheit vor; Zerhäckseln ab zwei Punkten, Gesundung und Nierenhieb solo bei Verletzung, Ausweiden bei vier Punkten (zwei, wenn das Ziel kurz vor dem Tod steht), Finsterer Stoß. Erinnerungen: Gifte, sobald erlernt, Tritt, Entrinnen solo."
L["rm.retail.rogue.assassination.Name"] = "Blizzard-Kampfassistent"
L["rm.retail.rogue.assassination.Description"] = "Empfohlen für Meucheln in Midnight. Im Kampf verbirgt das Spiel nun Ihre Blutungen, Stärkungszauber, Energie, Abklingzeiten und Gesundheit vor Addons, daher zeigt diese Rotation den eigenen Vorschlag von Blizzards Kampfassistent (die Ein-Tasten-Rotation, die den Eröffner aus der Verstohlenheit, Erdrosseln, Blutung, Vergiften, Todesmal und Königsmord übernimmt) und pausiert, während Sie wirken oder kein Gegner anvisiert ist. Erinnerungen an das, was er auslässt: ein tödliches und ein nicht tödliches Gift sowie Verstohlenheit zwischen den Kämpfen, Verschwinden, wenn Sie im Kampf nicht in Verstohlenheit sind, Tritt bei einem unterbrechbaren Zauber (er leuchtet nur dort auf, wo das Spiel den Zauber auslesen lässt). Die Gesundheit ist unter Retail verborgen, daher bleibt Blutrote Phiole Ihnen überlassen."
L["rm.retail.rogue.assassination.icyveins.Name"] = "Referenz (Icy Veins)"
L["rm.retail.rogue.assassination.icyveins.Description"] = "Nur als Referenz, standardmäßig deaktiviert: die Reihenfolge von Icy Veins und SimulationCraft hält Blutungen anhand ihrer Timer aufrecht, die Midnight im Kampf verbirgt; Energie ist unter Retail verborgen, daher entfällt das Ansammeln von Energie. Aus der Verstohlenheit Erdrosseln, dann Hinterhalt. Erdrosseln in seinen letzten 30 %, solange Sie nicht die vollen Combopunkte haben, Blutung bei 5+ in ihren letzten 30 %; bei 5+ Combopunkten Gnadenstoß oder Vergiften; darunter Blutroter Sturm gegen drei oder mehr Gegner, Dolchfächer gegen zwei oder mehr in der Nähe, Hinterhalt, Verstümmeln. Erinnerungen: Todesmal bei beiden aktiven Blutungen, Königsmord zusammen damit, Verschwinden bei bereitem Todesmal, Tückische Klinge auf ein Ziel mit Mal des Todespirschers, Disteltee, wann immer er im Kampf bereit ist, dazu die gemeinsamen Erinnerungen an Gifte, Verstohlenheit und Tritt."
L["rm.retail.rogue.initial.Name"] = "Blizzard-Kampfassistent"
L["rm.retail.rogue.initial.Description"] = "Empfohlen, bevor Sie eine Spezialisierung wählen (solange das Spiel die Anfangsspezialisierung des Schurken meldet). Hebt den Zauber hervor, den Blizzards Kampfassistent als Nächstes vorschlägt, den einzigen Rotationshinweis, den das Spiel ein Addon im Kampf in Midnight noch auslesen lässt; sie wartet, während Sie wirken oder kanalisieren. Daneben die Erinnerungen, die jede integrierte Schurke-Rotation teilt, jeweils sobald Sie den Zauber kennen. Wenn Sie auf Stufe 10 eine Spezialisierung wählen, übernehmen die integrierten Rotationen dieser Spezialisierung."
L["rm.retail.rogue.outlaw.Name"] = "Blizzard-Kampfassistent"
L["rm.retail.rogue.outlaw.Description"] = "Empfohlen für Gesetzlosigkeit in Midnight. Zeigt den Vorschlag von Blizzards Kampfassistent (er übernimmt den Eröffner aus der Verstohlenheit, Schicksalswürfel, Klingenwirbel, Adrenalinrausch, Zwischen die Augen und die Finisher) und pausiert, während Sie wirken oder kein Gegner anvisiert ist. Erinnerungen an das, was er auslässt: Gifte und Verstohlenheit zwischen den Kämpfen, Verschwinden, wenn Sie im Kampf nicht in Verstohlenheit sind, Tritt. Die Gesundheit ist unter Retail verborgen, daher bleibt Blutrote Phiole Ihnen überlassen. Großer Wurf bleibt Ihnen überlassen: Das Spiel verbirgt, wie viele Stärkungszauber von Schicksalswürfel Sie haben."
L["rm.retail.rogue.outlaw.icyveins.Name"] = "Referenz (Icy Veins)"
L["rm.retail.rogue.outlaw.icyveins.Description"] = "Nur als Referenz, standardmäßig deaktiviert: die Reihenfolge von Icy Veins, SimulationCraft und Wowhead liest die Stärkungszauber von Schicksalswürfel, Stapel von Gelegenheit und Energie, die Midnight im Kampf verbirgt. Aus der Verstohlenheit Hinterhalt. Ab einem Combopunkt unter dem Maximum: Zwischen die Augen, Mordlust, Gnadenstoß, Tötung. Sonst Hinterhalt mit Unverfroren, Pistolenschuss bei sechs Stapeln Gelegenheit (drei bei wenigen Combopunkten), Hinterhalt, Finsterer Stoß. Erinnerungen: Schicksalswürfel ohne aktiven Wurf, Adrenalinrausch bei zwei oder weniger Combopunkten, Klingenwirbel gegen zwei oder mehr Gegner aufrechterhalten, Klingenansturm, Vorbereitung, wenn Adrenalinrausch, Zwischen die Augen und Klingenansturm alle abklingen. Großer Wurf bleibt manuell."
L["rm.retail.rogue.subtlety.Name"] = "Blizzard-Kampfassistent"
L["rm.retail.rogue.subtlety.Description"] = "Empfohlen für Täuschung in Midnight. Zeigt den Vorschlag von Blizzards Kampfassistent (er übernimmt den Eröffner aus der Verstohlenheit, Schattenklingen, Blutschlunds Biss, Schattentanz, Geheimtechnik und die Finisher) und pausiert, während Sie wirken oder kein Gegner anvisiert ist. Erinnerungen an das, was er auslässt: Gifte und Verstohlenheit zwischen den Kämpfen, Tritt bei einem unterbrechbaren Zauber. Die Gesundheit ist unter Retail verborgen, daher bleibt Blutrote Phiole Ihnen überlassen."
L["rm.retail.rogue.subtlety.icyveins.Name"] = "Referenz (Icy Veins)"
L["rm.retail.rogue.subtlety.icyveins.Description"] = "Nur als Referenz, standardmäßig deaktiviert: die Reihenfolge von Icy Veins und SimulationCraft hält Schattentanz für Geheimtechnik zurück und liest Schattentanz, Dunkelste Nacht und Energie, die Midnight im Kampf verbirgt. In Verstohlenheit vor dem Pull: Schattenschlag. Ab einem Combopunkt unter dem Maximum: Ausweiden mit Dunkelster Nacht, Geheimtechnik während Schattentanz, Gnadenstoß, Schwarzpulver gegen drei oder mehr Gegner, Ausweiden. Sonst Schattenschlag, Shurikensturm gegen zwei oder mehr, Düstere Klinge oder Meucheln. Erinnerungen: Blutschlunds Biss während Schattentanz, Schattenklingen bei bereitem Schattentanz, Schattentanz bei zwei oder weniger (oder sechs oder mehr) Combopunkten, wenn Geheimtechnik bereit oder Schattenklingen aktiv ist, Verschwinden außerhalb der Verstohlenheit bei zwei oder weniger Combopunkten."
L["rm.sod.rogue.dps.Name"] = "Nahkampf-DPS (SoD)"
L["rm.sod.rogue.dps.Description"] = "Saison der Entdeckungen, Stufen 1–60 mit Runen, sobald Sie sie gravieren; zusammengestellt aus Simulation Phase 6, Icy Veins und Zockify Phase 8. Aus der Verstohlenheit: Schattenschlag, Erdrosseln in einer Gruppe, Hinterhalt für einen Meucheln-Build mit einem Dolch, Fieser Trick solo. Wenn drei oder mehr Gegner gegen Sie kämpfen: zuerst Donnerbüchse, Blutroter Sturm, Dolchfächer. Dann Hinterhalt bei einem Proc von Halsabschneider (mit einem Dolch), Säbelschlitzer bei drei Stapeln gehalten, Vergiftetes Messer bei vier Giftstapeln, Zerhäckseln ab zwei Punkten (ab vier erneuert, außer mit eingravierter Rune „Cut to the Chase“), Rüstung schwächen übernehmen, wenn niemand Rüstung zerreißen nutzt oder Zähes Gift aufrechterhält, mit eingravierter Rune Massaker eine Blutung (Blutroter Sturm, sonst Blutung; keine mit Säbelschlitzer), Vergiften bei fünf Punkten (Ausweiden, bis Sie es gravieren) und ein Aufbauangriff je nach Handschuhrune: Verstümmeln, Säbelschlitzer, Meucheln (mit einem Dolch), sonst Finsterer Stoß. Erinnerungen: eine temporäre Verzauberung auf jeder Waffe, Tritt, Disteltee, Klingenwirbel, Adrenalinrausch, Kaltblütigkeit und Entrinnen sowie mit eingravierter Rune Meister des hinterhältigen Angriffs Verschwinden, um sie zu erneuern, und Vorbereitung."
L["rm.sod.rogue.dps.icyveins.Name"] = "Nahkampf-DPS, Blutung für Massaker (SoD, Icy Veins)"
L["rm.sod.rogue.dps.icyveins.Description"] = "Die Reihenfolge von Icy Veins für die Saison der Entdeckungen, eine Alternative zur empfohlenen integrierten Nahkampf-DPS-Rotation der Saison der Entdeckungen, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Jeder Finisher bei fünf Combopunkten, zuerst Zerhäckseln, wenn es fehlt oder ausläuft, dann Blutung aufrechterhalten, wenn Massaker eingraviert ist, dann Vergiften; Vergiftetes Messer nur bei fünf Giftstapeln; Donnerbüchse oder Dolchfächer gegen drei Gegner. Dieselben Eröffner, Aufbauangriffe und Erinnerungen wie die empfohlene integrierte Rotation; das Aufrechterhalten von Zähes Gift bleibt Ihnen überlassen."
L["rm.sod.rogue.dps.zockify.Name"] = "Nahkampf-DPS, schlankes Vergiften (SoD, Zockify)"
L["rm.sod.rogue.dps.zockify.Description"] = "Die schlanke Liste von Zockify für die Saison der Entdeckungen, eine Alternative zur empfohlenen integrierten Nahkampf-DPS-Rotation der Saison der Entdeckungen, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Keine Blutungen und kein Rüstung schwächen. Vergiftetes Messer bei vier Giftstapeln, Zerhäckseln, wenn es fehlt (ab zwei Punkten, mit Säbelschlitzer ab vier), Vergiften bei fünf Punkten, dann der Aufbauangriff der Handschuhrune. Der Burst mit Verschwinden und Kaltblütigkeit bleibt Ihnen überlassen."
L["rm.sod.rogue.tank.Name"] = "Tank (SoD)"
L["rm.sod.rogue.tank.Description"] = "Tank in der Saison der Entdeckungen, gewählt, wenn Nur eine Fleischwunde graviert ist; zusammengestellt aus Simulation Phase 6, Icy Veins, Zockify und Warcraft Tavern. Riposte, Parierdolch bei Abklingzeit-Ende, Klingentanz ab einem Combopunkt (ab drei erneuert), Zerhäckseln ab drei (ab vier erneuert), Dolchfächer, Blutroter Sturm und Donnerbüchse gegen drei oder mehr Gegner, Donnerbüchse, solange Klingentanz aktiv ist, Ausweiden bei fünf Punkten, wenn beide Stärkungszauber aktiv sind, Vergiftetes Messer bei wenig Energie, dann Säbelschlitzer, Verstümmeln oder Finsterer Stoß. Erinnerungen: Reizen in einer Gruppe, wenn Ihr Ziel jemand anderen angreift, Tritt, Entrinnen unter halber Gesundheit, Klingenwirbel, Adrenalinrausch, Disteltee und Waffengifte (das der Schildhand nur mit einer Schildhandwaffe). Schattenschritt und das Aufrechterhalten von Zähes Gift bleiben Ihnen überlassen."
L["rm.tbc.rogue.dps.simulator.Name"] = "Nahkampf-DPS (Simulation)"
L["rm.tbc.rogue.dps.simulator.Description"] = "Stufen 1–70, jede Spezialisierung. Aus der Verstohlenheit: Konzentration, dann Fieser Trick solo oder Erdrosseln in einer Gruppe, sonst Hinterhalt (mit einem Dolch in der Waffenhand). Im Kampf: Riposte, Zerhäckseln ab zwei Combopunkten (in seinen letzten zwei Sekunden erneuert), Ausweiden auf ein Ziel kurz vor dem Tod und bei fünf Punkten Blutung, wenn sie voll wirken kann (nicht während Klingenwirbel mehrere Ziele trifft), sonst Ausweiden. Baut mit Verstümmeln oder Meucheln (Dolch) auf, wenn das Ziel Sie nicht angreift, sonst mit Blutsturz oder Finsterem Stoß. Erinnert an fehlende Gifte, Tritt, Klingenwirbel und Adrenalinrausch, Kaltblütigkeit und Entrinnen. Rüstung schwächen, Nierenhieb, Finte, Verschwinden und Positionierung bleiben Ihnen überlassen."
L["rm.tbc.rogue.dps.wowhead.Name"] = "Nahkampf-DPS (Wowhead)"
L["rm.tbc.rogue.dps.wowhead.Description"] = "Stufen 1–70, jede Spezialisierung, nach Wowhead. Dieselben Eröffner aus der Verstohlenheit, Aufbauangriffe und Erinnerungen wie die Simulation-Version, aber Zerhäckseln beginnt ab einem Combopunkt und jeder Finisher mit fünf Punkten ist Ausweiden: keine Blutung. Rüstung schwächen, Nierenhieb, Finte, Verschwinden und Positionierung bleiben Ihnen überlassen. Eine Alternative zur empfohlenen integrierten Nahkampf-DPS-Rotation nach Simulation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität."
